create table if not exists leagues (id text primary key, name text not null, season integer not null);
create table if not exists teams (league_id text references leagues(id) on delete cascade, id text not null, name text not null, primary key (league_id,id));
create table if not exists ranking_snapshots (id bigint generated always as identity primary key, league_id text not null references leagues(id) on delete cascade, season integer not null, week integer not null, created_at timestamptz not null default now(), unique (league_id,season,week));
create table if not exists team_ranking_snapshots (snapshot_id bigint not null references ranking_snapshots(id) on delete cascade, team_id text not null, rank integer not null, power_score numeric not null, scoring_score numeric not null, recent_form_score numeric not null, record_score numeric not null, expected_wins_score numeric not null, roster_score numeric not null, schedule_score numeric not null, primary key (snapshot_id,team_id));
